const input = $json;

const query = typeof input.query === 'string' ? input.query.trim() : '';
if (!query) {
  throw new Error('Input contract violation: "query" must be a non-empty string.');
}

const sourceContext = typeof input.source_context === 'string'
  ? input.source_context.trim()
  : '';

const allowedSourceTypes = new Set(['approved', 'draft', 'tracker', 'unknown']);
const requestedSourceType = typeof input.source_type === 'string'
  ? input.source_type.trim().toLowerCase()
  : 'unknown';
const sourceType = allowedSourceTypes.has(requestedSourceType)
  ? requestedSourceType
  : 'unknown';

return {
  json: {
    query,
    source_context: sourceContext,
    source_type: sourceType,
    conversation_id: typeof input.conversation_id === 'string' ? input.conversation_id.trim() : '',
    context_available: sourceContext.length > 0
  }
};

