parameters.jsCode:
const input = query && typeof query === 'object' ? query : {};
const draft = typeof input.draft === 'string' ? input.draft : '';
const sourceType = typeof input.source_type === 'string'
  ? input.source_type.toLowerCase()
  : 'unknown';

const legalPatterns = [
  /\blegal advice\b/i,
  /\blegally (?:required|binding|valid|invalid)\b/i,
  /\bguarantee(?:d|s)?\b/i,
  /\bmust comply with the law\b/i,
  /\bthis means legally\b/i
];
const matchedPatterns = legalPatterns
  .filter((pattern) => pattern.test(draft))
  .map((pattern) => pattern.source);

const humanValidationRequired = sourceType !== 'approved';
return JSON.stringify({
  legal_interpretation_risk: matchedPatterns.length > 0,
  human_validation_required: humanValidationRequired,
  notes: [
    ...(matchedPatterns.length > 0
      ? ['Remove legal interpretation and state only source-supported facts.']
      : []),
    ...(humanValidationRequired
      ? ['The source is not classified as approved; human validation is required.']
      : [])
  ]
});

