    },
    "source_type": {
      "type": "string",
      "enum": ["approved", "draft", "tracker", "unknown"],
      "description": "The source classification supplied in the user message."
    }
  },
  "required": ["draft", "source_type"],
  "additionalProperties": false
}

parameters.jsCode:
let result = $json.output;

if (typeof result === 'string') {
  try {
    result = JSON.parse(result);
  } catch (error) {
    throw new Error(`Structured output is not valid JSON: ${error.message}`);
  }
}

if (!result || typeof result !== 'object' || Array.isArray(result)) {
  throw new Error('Structured output must be an object.');
}

const statuses = new Set(['answered', 'not_found', 'human_validation_required']);
if (!statuses.has(result.status)) {
  throw new Error(`Unexpected status: ${String(result.status)}`);
}
if (typeof result.answer !== 'string' || !result.answer.trim()) {
  throw new Error('Structured output must contain a non-empty answer.');
}
if (!result.process || typeof result.process !== 'object') {
  throw new Error('Structured output is missing process details.');
}
if (!Array.isArray(result.evidence)) {
  throw new Error('Structured output evidence must be an array.');
}
if (!result.governance || typeof result.governance !== 'object') {
  throw new Error('Structured output is missing governance details.');
}
if (result.status === 'not_found') {
  result.answer = 'I could not find this in the connected ISP knowledge sources.';
  result.evidence = [];
}
if (result.governance.legal_interpretation_risk === true) {
  throw new Error('Governance validation failed: the answer may contain legal interpretation.');
}

return {
  json: {
    success: true,
    ...result
  }
};
